        Owner owner;const auto s=owner.session;check(PN2S_SetStrategy(s,PN2S_OFFSET_RECOVERED)==0&&PN2S_SetPitch(s,.5)==0,"Choose actual explicit recovered Offset continuation route");const auto all=instances(s,rectangle(s),10);const auto sheet=PN2_AddSheet(s,4,6);const std::array sheets{sheet,sheet};const std::array counts{2,1};const std::array oldParts{all[0],all[1],all[2]};const std::array poses{PN2_CreateOrientation(45),PN2_CreateOrientation(0),PN2_CreateOrientation(0)};const std::array<PN2_Point,3> positions{{{0,0},{0,0},{0,0}}};const auto previous=PN2_MultiPreNest(s,2,sheets.data(),counts.data(),oldParts.data(),poses.data(),positions.data());const auto source=snapshot(s,previous);int oldMissing=-1;PN2_Part oldMissingPart=nullptr;check(PN2S_GetMultiUnplacedCount(s,previous,&oldMissing)==0&&oldMissing==1&&PN2S_GetMultiUnplacedPart(s,previous,0,&oldMissingPart)==0&&oldMissingPart==all[0],"Actual source contains rejected old manual demand");
        std::vector<PN2_Part> added(all.begin()+3,all.begin()+9);const auto savedAdded=added;const std::array stockQuantities{1,1};const auto next=PN2_MultiNestMore(s,previous,sheets.data(),2,stockQuantities.data(),added.data(),int(added.size()),20.);const auto output=snapshot(s,next);const auto ids=identities(output);check(output.size()==2&&ids.size()==8&&!ids.contains(id(all[0]))&&ids.contains(id(all[8])),"Actual global native continuation fills both existing boards and drops old missing demand without consuming unnecessary new stock");noMissing(s,next);oldPrefix(source,output);check(added==savedAdded&&snapshot(s,previous)==source,"Successful continuation copies caller arrays and leaves original live result unchanged");++cases;boardCases+=output.size();placed+=ids.size();
        std::array readd{all[0],all[3]};const auto retried=PN2_MultiNestMore(s,previous,nullptr,0,nullptr,readd.data(),2,20.);const auto retry=snapshot(s,retried);check(identities(retry)==std::set<uintptr_t>{id(all[0]),id(all[1]),id(all[2]),id(all[3])},"Previously rejected SDK ID becomes current new material when explicitly resubmitted");noMissing(s,retried);oldPrefix(source,retry);++cases;boardCases+=retry.size();placed+=4;
        const auto zero=PN2_MultiNestMore(s,previous,nullptr,0,nullptr,nullptr,0,20.);const auto unchanged=snapshot(s,zero);check(unchanged==source,"Zero current additions preserves old physical board geometry and discards old missing input");noMissing(s,zero);++cases;
        std::array duplicateOld{all[1]};error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,duplicateOld.data(),1,20.),PN2S_UNSUPPORTED);std::array duplicateNew{all[3],all[3]};error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,duplicateNew.data(),2,20.),PN2S_UNSUPPORTED);
        error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,nullptr,1,20.),PN2S_INVALID);error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,nullptr,-1,20.),PN2S_INVALID);error(PN2_MultiNestMore(s,previous,nullptr,-1,nullptr,readd.data(),2,20.),PN2S_INVALID);error(PN2_MultiNestMore(s,previous,nullptr,1,stockQuantities.data(),readd.data(),2,20.),PN2S_INVALID);error(PN2_MultiNestMore(s,previous,sheets.data(),2,nullptr,readd.data(),2,20.),PN2S_INVALID);
        error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,nullptr,0,0.),PN2S_INVALID);error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,nullptr,0,std::numeric_limits<double>::quiet_NaN()),PN2S_INVALID);
        Owner foreign;const auto alien=instances(foreign.session,rectangle(foreign.session),1);auto alienPart=alien[0];error(PN2_MultiNestMore(s,previous,nullptr,0,nullptr,&alienPart,1,20.),PN2S_INVALID);error(PN2_MultiNestMore(foreign.session,previous,nullptr,0,nullptr,nullptr,0,20.),PN2S_INVALID);
